23	     */
24	    public static String of(LocalDate birthDate, LocalDate asAt) {
25	        int years = Period.between(birthDate, asAt).getYears();
26	        if (years < 18) {
27	            return "MINOR";
28	        }
29	        if (years < 65) {
30	            return "ADULT";
31	        }
32	        return "SENIOR";
