        }
        if (Integer.valueOf(0).equals(this.namesakeCount)) {
            points += 1;
        }
        if (this.householdSize != null && this.householdSize >= 3) {
            points += 2;
        }
        if (getTenureDays() > 365) {
            points += 3;
